const items = $input.all();
const out = [];

for (const item of items) {
  const original = item.json;

  // garante tipos corretos
  const id = Number(original.id);
  const row_number = original.row_number;
  const whatsapp = original.whatsapp;

  // texto completo vindo do agente
  const texto = original.output || original.mensagem || '';

  // divide em 3 blocos pelo pipe
  const partes = texto.split('|').map(p => p.trim());

  const total = partes.length;

  partes.forEach((parte, index) => {
    out.push({
      json: {
        ...original,        // preserva TODO o contexto
        id,                 // id como NUMBER
        row_number,         // mantém row_number
        whatsapp,           // mantém telefone
        mensagem: parte,    // mensagem individual
        ordem: index + 1,   // 1, 2, 3
        total               // total de mensagens
      }
    });
  });
}

return out;

// Obtém os dados do item atual do loop
const currentItem = $input.item.json;

// Extrai informações do contexto do loop atual
const rowNumber = currentItem.row_number;
const whatsappNumber = currentItem.whatsapp;
const itemId = currentItem.id;
const evoOutput = currentItem.output;

// Função para normalizar número de WhatsApp (remove caracteres especiais)
function normalizePhone(phone) {
  if (!phone) return '';
  return String(phone).replace(/\D/g, '');
}

// Inicializa flag de erro
let hasImageError = false;
let errorDetails = null;

// Valida se existe output do EVO
if (evoOutput) {
  try {
    // Se output for string, tenta parsear como JSON
    const outputData = typeof evoOutput === 'string' ? JSON.parse(evoOutput) : evoOutput;

    // Verifica se é um array
    if (Array.isArray(outputData)) {
      // Procura por erro de imagem no array
      for (const item of outputData) {
        if (item && item.error === "Erro ao enviar imagem") {
          // Valida se o erro corresponde ao número do loop atual
          if (item.whatsapp || item.numero || item.phone) {
            const errorPhone = normalizePhone(item.whatsapp || item.numero || item.phone);
            const currentPhone = normalizePhone(whatsappNumber);

            // Confirma que o erro é do número atual
            if (errorPhone === currentPhone) {
              hasImageError = true;
              errorDetails = item;
              break;
            }
          } else {
            // Se não há identificação de número no erro, assume que é do loop atual
            hasImageError = true;
            errorDetails = item;
            break;
          }
        }
      }
    } else if (outputData && outputData.error === "Erro ao enviar imagem") {
      // Caso seja objeto único
      hasImageError = true;
      errorDetails = outputData;
    }
  } catch (e) {
    // Se houver erro no parse, verifica se a string contém o erro
    if (typeof evoOutput === 'string' && evoOutput.includes("Erro ao enviar imagem")) {
      hasImageError = true;
      errorDetails = { error: "Erro ao enviar imagem", raw: evoOutput };
    }
  }
}

// Prepara o retorno
if (hasImageError) {
  // Erro válido encontrado para o número do loop atual
  return {
    json: {
      has_error: true,
      error_type: "image_send_failure",
      row_number: rowNumber,
      whatsapp: whatsappNumber,
      id: itemId,
      error_message: "Erro ao enviar imagem",
      error_details: errorDetails,
      timestamp: new Date().toISOString(),
      loop_processed: true,
      // Dados prontos para atualizar a planilha
      spreadsheet_update: {
        row: rowNumber,
        status: "ERRO",
        error_reason: "Falha no envio de imagem",
        whatsapp_number: whatsappNumber,
        processed_at: new Date().toISOString()
      }
    }
  };
} else {
  // Nenhum erro ou erro não corresponde ao loop atual
  return {
    json: {
      has_error: false,
      row_number: rowNumber,
      whatsapp: whatsappNumber,
      id: itemId,
      loop_processed: true,
      message: "Nenhum erro de imagem detectado para este número"
    }
  };
}

