const items = $input.all();
const results = [];
for (const item of items) {
    const json = item.json;
    let phone = '';
    let instance = 'PR2';
    let origin = 'unknown';

    if (json.body && json.body.key && json.body.key.remoteJid) {
        phone = json.body.key.remoteJid;
        instance = json.instance || 'PR2';
        origin = 'inbound';
    } else if (json.whatsapp) {
        phone = json.whatsapp.toString();
        origin = 'outbound';
    } else if (json.remoteJid) {
        phone = json.remoteJid;
        origin = 'inbound_processed';
    }

    let cleanPhone = phone.replace(/\D/g, '');
    if (cleanPhone.length === 11 && !cleanPhone.startsWith('55')) cleanPhone = '55' + cleanPhone;

    const conversation_id = `${instance}_${cleanPhone}`;
    results.push({ json: { ...json, conversation_id, flow_origin: origin } });
}
return results;

const crypto = require('crypto');
const items = $input.all();
const results = [];
for (const item of items) {
    const text = item.json.output || item.json.text || '';
    const hash = crypto.createHash('md5').update(text).digest('hex');
    results.push({ json: { ...item.json, msg_hash: hash } });
}
return results;

